from typing import List, Set, Any

def common_in_nested_lists(nestedlist: List[List[Any]]) -> Set[Any]:
    if not nestedlist:
        return set()

    common = set(nestedlist[0])
    for sub in nestedlist[1:]:
        common &= set(sub)

    return common

# === 測試驗證 ===
if __name__ == "__main__":
    assert set(common_in_nested_lists([[12, 18, 23, 25, 45], 
                                       [7, 12, 18, 24, 28], 
                                       [1, 5, 8, 12, 15, 16, 18]])) == set([18, 12])

    assert common_in_nested_lists([]) == set()
    assert common_in_nested_lists([[1, 2, 3]]) == {1, 2, 3}
    assert common_in_nested_lists([[1, 2], []]) == set()
    assert common_in_nested_lists([[-5, -2], [-2, 0], [-5, -2, -2]]) == {-2}

    print("All tests passed.")
