def smallest_num(xs):
    assert isinstance(xs, list), "invalid inputs"
    assert all(isinstance(item, (int, float)) for item in xs), "invalid inputs"

    if not xs:
        raise ValueError("Input list cannot be empty")

    min_val = xs[0]
    for i in range(1, len(xs)):
        if xs[i] < min_val:
            min_val = xs[i]

    return min_val
